t.script:
(function(){
  function isDeco(){
    var p=new URL(window.location.href).searchParams;
    if(p.get('variant')==='209229')return true;
    if(p.get('variant'))return false;
    var n=document.querySelector('#product_details input[name="ptal-20926"]:checked');
    if(n && (n.value==='184971'||n.getAttribute('data-attribute-value-id')==='75044'))return true;
    var h=document.querySelector('#product_details input.product_id[name="product_id"]');
    return Boolean(h && h.value==='209229');
  }
  function guard(){
    var b=document.getElementById('add_to_cart');
    if(!b)return;
    if(isDeco()){
      if(!b.hasAttribute('data-dt8-original-class')){
        b.setAttribute('data-dt8-original-class',b.className);
        b.setAttribute('data-dt8-original-href',b.getAttribute('href')||'#');
        b.setAttribute('data-dt8-original-html',b.innerHTML);
      }
      b.classList.remove('js_check_product','a-submit');
      b.setAttribute('href','/contact-us');
      b.setAttribute('data-dt8-deco-carton-guard','1');
      b.innerHTML='Request carton details &rarr;';
      b.setAttribute('aria-label','Request confirmed carton details for Rhythm White Deco');
    }else if(b.hasAttribute('data-dt8-original-class')){
      b.className=b.getAttribute('data-dt8-original-class');
      b.setAttribute('href',b.getAttribute('data-dt8-original-href')||'#');
      b.innerHTML=b.getAttribute('data-dt8-original-html')||'ADD TO ORDER';
      b.removeAttribute('data-dt8-deco-carton-guard');
      b.removeAttribute('aria-label');
    }
  }
  document.addEventListener('click',function(e){
    if(!isDeco())return;
    var t=e.target.closest('#add_to_cart');
    if(t){e.preventDefault();e.stopImmediatePropagation();window.location.assign('/contact-us');}
  },true);
  document.addEventListener('submit',function(e){
    if(isDeco() && e.target.closest('#o_wsale_product_details_content')){
      e.preventDefault();e.stopImmediatePropagation();
    }
  },true);
  document.addEventListener('change',function(e){
    if(e.target.closest('#product_details')){guard();window.setTimeout(guard,90);}
  },true);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',guard);
  else guard();
  window.addEventListener('popstate',guard);
})();

div.script:
(function(){
  /* DT8_PREMIUM_PURCHASE_SEQUENCE_V1: preserve original form and Add to Order. */
  function arrange(){
    var box=document.querySelector('#product_details.dt8-fixed-layout');
    if(!box)return;
    var price=box.querySelector('#dt8-pricing-v2');
    var calc=box.querySelector('#b2b_tile_calculator');
    var cta=box.querySelector('.o_wsale_product_details_content_section_cta');
    if(!price || !calc || !cta)return;
    calc.parentNode.insertBefore(price,calc);
    calc.insertAdjacentElement('afterend',cta);
    var help=box.querySelector('.dt8-tile-assistance');
    if(help)cta.insertAdjacentElement('afterend',help);
    Array.prototype.forEach.call(price.querySelectorAll('.dt8-price-columns div'),function(col){
      Array.prototype.forEach.call(Array.prototype.slice.call(col.querySelectorAll('strong'),1),function(node){node.style.display='none';});
    });
    box.classList.add('dt8-flow-clean');
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',arrange);
  else arrange();
  window.setTimeout(arrange,350);
  /* DT8_FLOW_INITIALIZATION_GUARD_V1: Odoo may initialize the tile calculator after DOM ready. */
  var root=document.getElementById('product_details');
  if(root){
    if(window.MutationObserver){
      var obs=new MutationObserver(function(){
        if(root.classList.contains('dt8-fixed-layout')){arrange();obs.disconnect();}
      });
      obs.observe(root,{attributes:true,attributeFilter:['class']});
      if(root.classList.contains('dt8-fixed-layout')){arrange();obs.disconnect();}
    }
    window.addEventListener('load',arrange,{once:true});
  }
})();

(function(){
  function startCodeDirectory(){
    var map=document.getElementById('dt8-variant-combinations');
    var code=document.getElementById('dt8-selected-item-code');
    var toggle=document.getElementById('dt8-all-codes-toggle');
    var list=document.getElementById('dt8-all-codes-list');
    var rows=document.getElementById('dt8-all-codes-rows');
    var copy=document.getElementById('dt8-copy-selected-code');
    var msg=document.getElementById('dt8-item-code-feedback');
    if(!map || !code || !toggle || !list || !rows || !copy)return;
    var entries=Array.prototype.slice.call(map.querySelectorAll('[data-variant-id][data-saleable="true"]'));
    function attr(el,name){return el.getAttribute('data-'+name)||'';}
    function selected(){
      var u=new URL(window.location.href),id=u.searchParams.get('variant');
      var vals=(u.searchParams.get('attribute_values')||'').split(',').filter(Boolean).sort().join(',');
      /* DT8_PREMIUM_DEFAULT_SKU_SYNC_V1: on clean URLs select the real native colour/combination, not the first Odoo variant. */
      var byValue=vals?entries.find(function(x){return attr(x,'attribute-values').split(',').filter(Boolean).sort().join(',')===vals;}):null;
      var byId=id?entries.find(function(x){return attr(x,'variant-id')===id;}):null;
      var selectedInputs=Array.prototype.map.call(document.querySelectorAll('#product_details .o_wsale_product_page_variants input.js_variant_change:checked'),function(n){return n.getAttribute('data-attribute-value-id')||'';}).filter(Boolean).sort().join(',');
      var bySelected=selectedInputs?entries.find(function(x){return attr(x,'combination')===selectedInputs;}):null;
      var colourLink=document.querySelector('#dt8-colour-feature .dt8-product-tone.is-selected');
      var nativeColour=colourLink?colourLink.getAttribute('data-colour-id'):'';
      var byColour=nativeColour?entries.find(function(x){return attr(x,'colour-id')===nativeColour;}):null;
      return byValue||byId||bySelected||byColour||entries[0]||null;
    }
    function put(tag,css,content){var e=document.createElement(tag);e.className=css;e.textContent=content;return e;}
    function refresh(){
      var pick=selected();
      if(!pick)return;
      var currentCode=attr(pick,'item-code')||'No code assigned';
      code.textContent=currentCode;
      copy.disabled=!attr(pick,'item-code');
      copy.setAttribute('aria-label','Copy '+currentCode);
      var colour=attr(pick,'colour-id'),shade=attr(pick,'colour-label')||'selected colour';
      var others=entries.filter(function(x){return attr(x,'colour-id')===colour;});
      rows.replaceChildren();
      others.forEach(function(x){
        var row=put('div','dt8-code-list-row'+(attr(x,'variant-id')===attr(pick,'variant-id')?' is-current':''),'');
        row.appendChild(put('span','dt8-code-size',attr(x,'size-label')||'—'));
        row.appendChild(put('span','dt8-code-finish',attr(x,'finish-label')||'—'));
        var target=new URL(window.location.href);
        target.searchParams.set('variant',attr(x,'variant-id'));
        target.searchParams.set('attribute_values',attr(x,'attribute-values'));
        target.searchParams.set('dt_colour_flow','1');
        var link=put('a','dt8-code-link',attr(x,'item-code')||'No code assigned');
        link.href=target.toString();
        link.setAttribute('title','Open '+(attr(x,'item-code')||'this combination'));
        row.appendChild(link);
        if(attr(x,'item-code')) {
          var rowCopy=put('button','dt8-code-row-copy','Copy');
          rowCopy.type='button';rowCopy.setAttribute('data-copy-item-code',attr(x,'item-code'));
          rowCopy.setAttribute('aria-label','Copy '+attr(x,'item-code'));
          row.appendChild(rowCopy);
        }
        rows.appendChild(row);
      });
      toggle.hidden=others.length<=1;
      if(toggle.hidden){list.hidden=true;toggle.setAttribute('aria-expanded','false');}
      toggle.textContent='View all '+others.length+' item codes for '+shade+' '+(list.hidden?'↓':'↑');
    }
    toggle.addEventListener('click',function(){
      list.hidden=!list.hidden;
      toggle.setAttribute('aria-expanded',String(!list.hidden));
      refresh();
      if(!list.hidden)list.scrollIntoView({behavior:'smooth',block:'nearest'});
    });
    function copyItemCode(value){
      if(!value||value==='No code assigned')return;
      function success(){if(msg)msg.textContent='Item code copied: '+value;}
      function fallback(){
        var input=document.createElement('textarea');
        input.value=value;input.style.position='fixed';input.style.opacity='0';
        document.body.appendChild(input);input.select();
        try{if(document.execCommand('copy'))success();else if(msg)msg.textContent='Select and copy the item code above.';}
        catch(e){if(msg)msg.textContent='Select and copy the item code above.';}
        input.remove();
      }
      if(navigator.clipboard && navigator.clipboard.writeText)navigator.clipboard.writeText(value).then(success).catch(fallback);
      else fallback();
    }
    copy.addEventListener('click',function(){copyItemCode(code.textContent.trim());});
    rows.addEventListener('click',function(event){
      var button=event.target.closest('button[data-copy-item-code]');
      if(button)copyItemCode(button.getAttribute('data-copy-item-code')||'');
    });
    refresh();
    window.addEventListener('popstate',refresh);
    document.addEventListener('change',function(event){
      if(event.target.closest('#product_details'))window.setTimeout(refresh,180);
    },true);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',startCodeDirectory);
  else startCodeDirectory();
})();

(function() {
    function init() {
        var box = document.getElementById('product_details');
        var hero = document.getElementById('dt8-colour-feature');
        var formatHead = document.getElementById('dt8-format-head');
        if (!box || !hero) return;
        /* DT8_QA_VARIANT_LINK_REPAIR_V2: canonicalize variant-only / conflicting deep links
           against actual, saleable product-variant attribute values before rendering. */
        try {
            var dt8Url=new URL(window.location.href);
            var dt8Wanted=dt8Url.searchParams.get('variant') || '';
            var dt8Map=document.getElementById('dt8-variant-combinations');
            var dt8Row=dt8Wanted && dt8Map ? dt8Map.querySelector('[data-variant-id="'+dt8Wanted+'"][data-saleable="true"]') : null;
            if (dt8Row) {
                var dt8Correct=dt8Row.getAttribute('data-attribute-values') || '';
                var dt8Current=dt8Url.searchParams.get('attribute_values') || '';
                var dt8Sort=function(x){return x.split(',').filter(Boolean).sort().join(',');};
                if (dt8Correct && dt8Sort(dt8Correct)!==dt8Sort(dt8Current)) {
                    dt8Url.searchParams.set('attribute_values',dt8Correct);
                    dt8Url.searchParams.set('dt_colour_flow','1');
                    window.location.replace(dt8Url.toString());
                    return;
                }
            }
        } catch (dt8LinkError) {}
        box.classList.add('dt8-modern-product');
        // DT8_COLOUR_LINK_FULL_NAV_V1: load the selected variant as a full product
        // page so palette-specific related suggestions and content refresh together.
        Array.prototype.forEach.call(box.querySelectorAll('a.dt8-product-tone'), function(link) {
            link.addEventListener('click', function(evt) {
                evt.preventDefault();
                evt.stopPropagation();
                window.location.assign(typeof box.dt8ColourDestination==='function' ? box.dt8ColourDestination(link) : link.href);
            }, true);
        });
        var attrs = box.querySelector('.o_wsale_product_details_content_section_attributes');
        if (attrs ? attrs.parentNode : false) {
            attrs.parentNode.insertBefore(hero, attrs);
            if (formatHead) attrs.parentNode.insertBefore(formatHead, attrs);
        }
        var colourInput = box.querySelector('li.variant_attribute[data-attribute-name="Colour"] input:checked,li.variant_attribute[data-attribute-name="Color"] input:checked');

        /* DT8_GUIDED_VARIANTS_20261014 + DT8_GUIDED_VARIANTS_DURABLE_20261016: operate only on real saleable product.product records; normalised XML operator encoding. */
        function setupGuidedVariants(){
            var map=document.getElementById('dt8-variant-combinations');
            var guide=document.getElementById('dt8-guided-variant-options');
            var palette=box.querySelector('.dt8-product-palette') || document.querySelector('#dt8-colour-feature .dt8-product-palette');
            if(!map || !guide || !palette || box.classList.contains('dt8-guided-active'))return;
            function makeKey(id,label){return id ? 'id:'+id : (label ? 'name:'+label.trim().toLowerCase() : '');}
            var records=Array.prototype.map.call(map.querySelectorAll('[data-variant-id]'),function(n){
                var vals=(n.getAttribute('data-attribute-values')||'').split(',').filter(Boolean);
                var cId=n.getAttribute('data-colour-id')||'',colour=n.getAttribute('data-colour-label')||'';
                var sId=n.getAttribute('data-size-id')||'',size=n.getAttribute('data-size-label')||'';
                var fId=n.getAttribute('data-finish-id')||'',finish=n.getAttribute('data-finish-label')||'';
                return {id:n.getAttribute('data-variant-id'),values:vals,colourId:cId,
                    colourKey:makeKey(cId,colour),sizeKey:makeKey(sId,size),size:size,
                    finishKey:makeKey(fId,finish),finish:finish,
                    saleable:n.getAttribute('data-saleable')==='true'};
            }).filter(function(v){return v.id ? v.saleable : false;});
            if(!records.length)return;
            var params=new URL(window.location.href).searchParams;
            var urlId=params.get('variant')||'';
            var hidden=box.querySelector('input.product_id[name="product_id"]');
            var inputId=hidden?hidden.value:'';
            /* DT8_PREMIUM_CORRECT_COLOUR_OPTIONS_V1: URL attribute combination outranks stale native default. */
            var attrToken=(params.get('attribute_values')||'').split(',').filter(Boolean).sort().join(',');
            var attrSelected=attrToken?records.find(function(v){return v.values.slice().sort().join(',')===attrToken;}):null;
            var checkedKey=Array.prototype.map.call(box.querySelectorAll('.o_wsale_product_page_variants input.js_variant_change:checked'),function(n){return n.getAttribute('data-attribute-value-id')||'';}).filter(Boolean).sort().join(',');
            var checkedSelected=checkedKey?records.find(function(v){return v.values.slice().sort().join(',')===checkedKey;}):null;
            var selected=records.find(function(v){return v.id===urlId;}) ||
                attrSelected || checkedSelected || records.find(function(v){return v.id===inputId;}) || records[0];
            var selectedColour=selected.colourKey;
            var available=records.filter(function(v){return v.colourKey===selectedColour;});
            if(!available.length)return;
            if(available.indexOf(selected)===-1)selected=available[0];
            function preferred(items){
                if(!items.length)return null;
                var wanted=new Set(selected.values);
                var ranked=items.slice().sort(function(a,b){
                    function score(v){return (v.id===selected.id?1000:0)+
                        (v.sizeKey===selected.sizeKey?50:0)+(v.finishKey===selected.finishKey?40:0)+
                        v.values.filter(function(val){return wanted.has(val);}).length;}
                    return score(b)-score(a);
                });
                return ranked[0];
            }
            function url(v){
                var u=new URL(window.location.href);
                u.searchParams.set('variant',v.id);
                u.searchParams.set('attribute_values',v.values.join(','));
                u.searchParams.set('dt_colour_flow','1');
                u.hash='';
                return u.toString();
            }
            function options(items,field,label){
                var result=[];
                items.forEach(function(v){
                    if(v[field] ? !result.some(function(p){return p.key===v[field];}) : false){
                        var same=items.filter(function(p){return p[field]===v[field];});
                        result.push({key:v[field],name:v[label],record:preferred(same)});
                    }
                });
                return result;
            }
            function render(groupId,choicesId,items,current){
                var group=document.getElementById(groupId);
                var holder=document.getElementById(choicesId);
                if(!group || !holder)return false;
                holder.replaceChildren();
                if(!items.length){group.hidden=true;return false;}
                items.forEach(function(item){
                    var isCurrent=item.key===current;
                    var elem=document.createElement(isCurrent?'span':'a');
                    elem.className='dt8-guided-choice'+(isCurrent?' is-selected':'');
                    elem.textContent=item.name;
                    if(isCurrent)elem.setAttribute('aria-current','true');
                    else if(item.record)elem.href=url(item.record);
                    holder.appendChild(elem);
                });
                group.hidden=false;return true;
            }
            var sizes=options(available,'sizeKey','size');
            var currentSize=selected.sizeKey || (sizes.length?sizes[0].key:'');
            var candidates=available.filter(function(v){return !currentSize || v.sizeKey===currentSize;});
            var finishes=options(candidates,'finishKey','finish');
            var currentFinish=selected.finishKey || (finishes.length?finishes[0].key:'');
            var sizesRendered=render('dt8-guided-size-group','dt8-guided-sizes',sizes,currentSize);
            var finishesRendered=render('dt8-guided-finish-group','dt8-guided-finishes',finishes,currentFinish);
            var onlyFinishNote=document.getElementById('dt8-finish-availability-note');
            if(onlyFinishNote) {
                onlyFinishNote.hidden=finishes.length!==1;
                onlyFinishNote.textContent=finishes.length===1 ? (selected.size+' is available in '+finishes[0].name+' only.') : '';
            }
            if(!sizesRendered ? !finishesRendered : false)return;
            guide.hidden=false;
            guide.setAttribute("data-dt8-ready","true");
            var hide={colour:!!selected.colourKey ? !!palette.querySelector('.dt8-product-tone') : false,
                size:sizesRendered,finish:finishesRendered};
            Array.prototype.forEach.call(box.querySelectorAll('.variant_attribute'),function(row){
                var name=(row.getAttribute('data-attribute-name')||
                    ((row.querySelector('.attribute_name')||{}).textContent||'')).trim().toLowerCase();
                var type=name.includes('colour')||name.includes('color')?'colour':
                    name.includes('size')||name.includes('format')?'size':name.includes('finish')?'finish':'';
                if(type ? hide[type] : false){
                    row.classList.add('dt8-native-variant-covered');
                    row.style.setProperty('display','none','important');
                }
            });
            box.classList.add('dt8-guided-active');
            box.dt8ColourDestination=function(link){
                var colourId=link.getAttribute('data-colour-id')||'';
                if(!colourId)return link.href;
                var candidates=records.filter(function(v){return v.colourId===colourId;});
                var chosen=preferred(candidates);
                return chosen?url(chosen):link.href;
            };
        }
        setupGuidedVariants();
        window.setTimeout(setupGuidedVariants,180);
        // DT8_AUTOMATIC_ALTERNATIVES_V2: refresh same-material/size
        // recommendations when native Odoo size/finish selection changes.
        // No Make/API writes and no product/price/stock mutation.
        var altRequestCounter = 0;
        var altTimer = null;
        var altCache = {};
        var baseAltPanel = document.getElementById('dt8-format-alternatives');
        function refreshMatchingAlternatives() {
            var existing = document.getElementById('dt8-format-alternatives');
            if (!existing) return;
            // DT8_ALTERNATIVE_VARIANT_MAP_V3: match the selected
            // Odoo attribute values; do not depend on asynchronous hidden product_id.
            var attrInput = Array.prototype.slice.call(box.querySelectorAll('.o_wsale_product_page_variants input.js_variant_change:checked'));
            var values = attrInput.map(function(el) { return el.getAttribute('data-attribute-value-id'); }).filter(Boolean);
            var selectedCombo = values.slice().sort().join(',');
            var map = document.getElementById('dt8-variant-combinations');
            var mapping = map ? Array.prototype.find.call(map.querySelectorAll('[data-combination]'),function(el) {
                return el.getAttribute('data-combination') === selectedCombo;
            }) : null;
            var variantField = box.querySelector('input.product_id');
            var variantId = mapping ? mapping.getAttribute('data-variant-id') : (variantField ? variantField.value : '');
            if (!variantId || existing.getAttribute('data-variant') === variantId) return;
            var seq = ++altRequestCounter;
            var target = new URL(window.location.href);
            target.searchParams.set('variant', variantId);
            if (values.length) target.searchParams.set('attribute_values',values.join(','));
            target.searchParams.delete('dt_alternatives');
            target.hash = '';
            var key = variantId + ':' + values.join(',');
            function paint(html) {
                if (seq !== altRequestCounter) return;
                var parsed = new DOMParser().parseFromString(html, 'text/html');
                var panel = parsed.getElementById('dt8-format-alternatives');
                var current = document.getElementById('dt8-format-alternatives');
                if (!panel || !current) return;
                panel.setAttribute('data-variant',variantId);
                panel.style.display=panel.querySelector('.dt8-matched-card')?'':'none';
                current.replaceWith(panel);
                /* DT8_RECOMMENDATIONS_REFRESH_V1: keep colour, specs and both galleries together. */
                var other=parsed.getElementById('dt8-related-colours');
                var present=document.getElementById('dt8-related-colours');
                if (other && present) {
                    other.style.display=other.querySelector('.dt8-related-card')?'':'none';
                    present.replaceWith(other);
                }
                var detail=parsed.getElementById('dt8-refined-specifications');
                var oldDetail=document.getElementById('dt8-refined-specifications');
                if (detail && oldDetail) oldDetail.replaceWith(detail);
            }
            if (altCache[key]) { paint(altCache[key]); return; }
            fetch(target.toString(), {credentials:'same-origin'})
                .then(function(resp) { if (!resp.ok) throw new Error('No matching alternatives');return resp.text(); })
                .then(function(html) { altCache[key]=html; paint(html); })
                .catch(function() { var el=document.getElementById('dt8-format-alternatives'); if(el) el.setAttribute('data-refresh-pending',''); });
        }
        function queueAlternativeRefresh(e) {
            if (e ? !e.target.closest('.variant_attribute') : false) return;
            if (altTimer) clearTimeout(altTimer);
            altTimer = setTimeout(refreshMatchingAlternatives,700);
        }
        document.addEventListener('click',queueAlternativeRefresh,true);
        document.addEventListener('change',queueAlternativeRefresh,true);
        /* Sync recommendations after Odoo initializes the real default combination. */
        window.setTimeout(refreshMatchingAlternatives,520);
        if (colourInput) {
            /* DT8_QA_VARIANT_LINK_REPAIR_V2: heading, selected chip and number reflect the actual checked colour. */
            var heading = document.getElementById('dt8-current-colour-heading');
            var actualColourId=colourInput.getAttribute('data-attribute-value-id') || '';
            var options=box.querySelectorAll('a.dt8-product-tone');
            var matched=null;
            Array.prototype.forEach.call(options,function(option){
                var yes=actualColourId && option.getAttribute('data-colour-id')===actualColourId;
                option.classList.toggle('is-selected',!!yes);
                if (yes){option.setAttribute('aria-current','true');matched=option;}
                else option.removeAttribute('aria-current');
            });
            if (heading) heading.textContent = colourInput.getAttribute('data-value-name') || heading.textContent;
            var currentNo=document.querySelector('#dt8-colour-feature .dt8-current-colour-number');
            var chipNo=matched ? matched.querySelector('.dt8-product-tone-number') : null;
            if (currentNo) {
                if (chipNo){currentNo.textContent='Colour '+chipNo.textContent.trim();currentNo.style.display='';}
                else currentNo.style.display='none';
            }
        }
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
})();

t.script:
(function(){
 /* DT8_PRICE_RESTORED_DURABLE_20261016: use actual Odoo MSRP and assigned price metadata, no unsafe XML operators. */
 function start(){
  var panel=document.getElementById('dt8-pricing-v2'),data=document.getElementById('dt8-price-data'),detail=document.getElementById('product_details');
  if(!panel || !data || !detail || panel.dataset.dt8Ready)return;
  panel.dataset.dt8Ready='1';
  var calc=document.getElementById('b2b_tile_calculator');
  if(calc)calc.insertAdjacentElement('afterend',panel);
  function money(n){return '$'+n.toLocaleString('en-CA',{minimumFractionDigits:2,maximumFractionDigits:2});}
  function fmt(n){return String(Math.round(n*100)/100);}
  function positive(n){return Number.isFinite(n)?Math.sign(n)===1:false;}
  function put(id,val){var el=document.getElementById(id);if(el)el.textContent=val;}
  function record(){
    var explicit=new URLSearchParams(window.location.search).get('variant')||'';
    if(explicit){var record=data.querySelector('[data-variant="'+explicit+'"]');if(record)return record;}
    var map=document.getElementById('dt8-variant-combinations'),id='',selected=Array.from(detail.querySelectorAll('.o_wsale_product_page_variants input.js_variant_change:checked')).map(function(n){return n.getAttribute('data-attribute-value-id')||'';}).filter(Boolean).sort().join(',');
    if(map ? Boolean(selected) : false)map.querySelectorAll('[data-combination]').forEach(function(n){if(n.getAttribute('data-combination')===selected)id=n.getAttribute('data-variant-id');});
    if(!id){var field=detail.querySelector('input.product_id');if(field)id=field.value;}
    return data.querySelector('[data-variant="'+id+'"]') || data.querySelector('[data-variant]');
  }
  function draw(){
    var v=record();if(!v)return;
    var retail=Number(v.getAttribute('data-msrp')||0),dealer=Number(v.getAttribute('data-net')||0);
    var unit=positive(dealer)?dealer:retail,ftbox=Number(v.getAttribute('data-ftbox')||0),pieces=Number(v.getAttribute('data-pcsbox')||0),ftpiece=Number(v.getAttribute('data-ftpiece')||0);
    if(!positive(ftpiece) ? (positive(ftbox)?positive(pieces):false) : false)ftpiece=ftbox/pieces;
