    });
  }
  document.addEventListener('dt8-qty-updated',draw);
  document.addEventListener('input',function(e){if(e.target ? Boolean(e.target.closest('#b2b_tile_calculator')) : false)draw();},true);
  document.addEventListener('change',function(e){if(e.target ? Boolean(e.target.closest('#product_details')) : false)window.setTimeout(draw,150);},true);
