(function(){
  function setup(){
    var button=document.getElementById('dt8-add-inquiry-direct');
    if(!button || button.dataset.bound)return;
    button.dataset.bound='1';
    // Older native add-to-inquiry enhancement is occasionally absent. Never show two CTAs.
    window.setTimeout(function(){
      var legacy=document.getElementById('b2b_ghost_cart_btn');
      if(legacy){button.hidden=true;return;}
      button.hidden=false;
      var native=document.getElementById('add_to_cart');
      if(native)native.style.setProperty('display','none','important');
    },850);
    function tell(message){var p=document.getElementById('dt8-inquiry-direct-feedback');if(p)p.textContent=message;}
    button.addEventListener('click',function(ev){
      ev.preventDefault();
      try{
        var id=new URLSearchParams(window.location.search).get('variant')||'';
        var field=document.querySelector('#product_details input.product_id[name="product_id"]');
        if(!id)id=field?field.value:'';
        if(!/^\d+$/.test(id))throw new Error('Please choose a product size or finish.');
        var data=document.getElementById('dt8-price-data');
        var node=data?data.querySelector('[data-variant="'+id+'"]'):null;
        var pack=document.querySelector('#dt8-verified-packaging-source [data-variant-id="'+id+'"]');
        if(!node || !pack)throw new Error('Product packaging or price is unavailable. Please refresh the selection.');
        var price=Number(node.getAttribute('data-net')||0);
        if(!(price>0))throw new Error('Account pricing is unavailable. Please contact Dalla Terra.');
        var ftbox=Number(pack.getAttribute('data-sqft')||0);
        var pieces=Number(pack.getAttribute('data-pieces')||0);
        var one=Number(pack.getAttribute('data-per-piece')||0);
        var qtyNode=document.getElementById('calc_boxes');
        var boxes=qtyNode?Number(qtyNode.value):0;
        if(!(boxes>0) || !(ftbox>0) || !(pieces>0))throw new Error('Enter a quantity and choose a product with verified packaging.');
        boxes=Math.ceil(boxes-0.000001);
        if(!(boxes>0))throw new Error('At least one full box is required.');
        if(!(one>0))one=ftbox/pieces;
        var sku=node.getAttribute('data-sku')||'';
        var displayed=document.getElementById('dt8-pricing-sku');
        if(displayed ? displayed.textContent.trim()!==sku : false)throw new Error('The selected SKU has changed. Please refresh product options.');
        var keyNode=document.getElementById('dt8_cart_storage_key');
        var key=keyNode?keyNode.value:'';
        if(!key || key.indexOf('b2b_ghost_cart_dt8_user_')!==0)throw new Error('Please sign in to your dealer account.');
        var old=localStorage.getItem(key);
        var cart=old?JSON.parse(old):[];
        if(!Array.isArray(cart))throw new Error('The Request List could not be read. No previous items were changed.');
        var qty=Number((boxes*ftbox).toFixed(3));
        var row={product_id:Number(id),qty:qty,price:price,name:sku,code:sku,isSqft:true,sqftPerPcs:one,pcsPerBox:pieces,fullBoxOnly:true,boxes:boxes,pieces:boxes*pieces};
        var found=cart.findIndex(function(item){return String(item.product_id||item.id)===String(id);});
        if(found>=0)cart[found]=row;else cart.push(row);
        localStorage.setItem(key,JSON.stringify(cart));
        tell(boxes+' full boxes / '+qty+' sq ft saved. Opening your request review.');
        window.location.assign('/b2b-quote-review');
      }catch(err){
        tell((err && err.message)?err.message:'Could not save this item; your existing inquiry was not changed.');
      }
    });
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',setup);else setup();
})();

(function(){
