  var sku=document.getElementById('b2b_dynamic_specs');
  if(sku ? Boolean(sku.parentNode) : false)sku.parentNode.insertBefore(root,sku);
  var attrs=details.querySelector('.o_wsale_product_details_content_section_attributes'),hero=document.getElementById('dt8-colour-feature'),format=document.getElementById('dt8-format-head');
  if(attrs ? Boolean(attrs.parentNode) : false){if(hero)attrs.parentNode.insertBefore(hero,attrs);if(format)attrs.parentNode.insertBefore(format,attrs);}
  var active='',last='area',lastNote='';
  function yes(n){return Number.isFinite(n) ? Math.sign(n)===1 : false;}
  function fmt(n){return String(Math.round(n*1000)/1000);}
  function writeAmount(el,n){var shown=fmt(n);el.value=shown;el.setAttribute('value',shown);}
  function variant(){
    var urlId=new URLSearchParams(window.location.search).get('variant')||'';
    if(urlId){var match=source.querySelector('[data-variant-id="'+urlId+'"]');if(match)return match;}
    var map=document.getElementById('dt8-variant-combinations'),id='';
    var selected=Array.from(details.querySelectorAll('.o_wsale_product_page_variants input.js_variant_change:checked')).map(function(n){return n.getAttribute('data-attribute-value-id')||'';}).filter(Boolean).sort().join(',');
    if(map ? Boolean(selected) : false)map.querySelectorAll('[data-combination]').forEach(function(n){if(n.getAttribute('data-combination')===selected)id=n.getAttribute('data-variant-id');});
    if(!id){var field=details.querySelector('input.product_id');if(field)id=field.value;}
    return source.querySelector('[data-variant-id="'+id+'"]') || source.querySelector('[data-variant-id]');
  }
  function notify(){details.dispatchEvent(new Event('dt8-qty-updated',{bubbles:true}));}
  function calculate(mode,commit){
    var v=variant();
    if(!v){msg.textContent='Choose a size and finish.';return;}
    active=v.getAttribute('data-variant-id');
    var sqft=Number(v.getAttribute('data-sqft')||0),pcs=Number(v.getAttribute('data-pieces')||0),each=Number(v.getAttribute('data-per-piece')||0);
    if(!yes(each) ? (yes(sqft)?yes(pcs):false) : false)each=sqft/pcs;
    sqLabel.textContent=yes(sqft)?fmt(sqft):'—';pcLabel.textContent=yes(pcs)?fmt(pcs):'—';
    if(!yes(sqft) || !yes(pcs) || !yes(each)){
      area.disabled=true;boxes.disabled=true;tiles.disabled=true;
      msg.textContent='Packaging needs confirmation. Please contact Dalla Terra.';return;
    }
    area.disabled=false;boxes.disabled=false;tiles.disabled=false;
    var input=mode==='tiles'?tiles:mode==='boxes'?boxes:area,requested=Number(input.value);
    if(input.value==='' || !yes(requested)){
      [area,boxes,tiles].forEach(function(el){if(el!==input){el.value='';el.removeAttribute('value');}});
      msg.textContent='Full boxes are used for Dalla Terra tile orders.';msg.classList.remove('dt8-rounding-note');notify();return;
    }
    var required=mode==='boxes'?requested:mode==='tiles'?requested/pcs:requested/sqft;
    var count=Math.max(1,Math.ceil(required-1e-9)),quantity=Math.round(count*pcs),covered=count*sqft;
    var fulfilled=mode==='tiles'?quantity:mode==='boxes'?count:covered;
    var rounded=Math.sign(fulfilled-requested-0.000001)===1;
    if(commit || mode!=='area')writeAmount(area,covered);
    if(commit || mode!=='boxes')writeAmount(boxes,count);
    if(commit || mode!=='tiles')writeAmount(tiles,quantity);
    if(rounded){
      lastNote='Rounded up from '+fmt(requested)+(mode==='area'?' sq ft':mode==='tiles'?' tiles':' boxes')+' to '+fmt(count)+(count===1?' full box':' full boxes')+' — '+fmt(covered)+' sq ft, '+fmt(quantity)+' tiles.';
      msg.textContent=lastNote;msg.classList.add('dt8-rounding-note');
    }else if(!lastNote){
