    field.addEventListener('blur',function(){if(field.value){last=mode;calculate(mode,true);}});
  });
  function changed(){window.setTimeout(function(){
    var v=variant(),id=v?v.getAttribute('data-variant-id'):'';
    if(id ? id!==active : false){lastNote='';calculate(last,true);}
