&amp;amp;amp;amp;amp;amp;amp;amp;lt;/t&amp;amp;amp;amp;amp;amp;amp;amp;gt;
window.b2bIsLoggedIn = ("&amp;amp;amp;amp;amp;amp;amp;amp;lt;t t-esc="request.env.user._is_public()"/&amp;amp;amp;amp;amp;amp;amp;amp;gt;" !== "True");
var viewMode = "&amp;amp;amp;amp;amp;amp;amp;amp;lt;t t-esc="view_mode"/&amp;amp;amp;amp;amp;amp;amp;amp;gt;";
