var unitLabel = showSqft ? 'Piece' : 'Each';

//
document.addEventListener('DOMContentLoaded', function() {

    /* =================================================================
       THE "DIRECT HIT" ROUTER FOR NATIVE SEARCH
       ================================================================= */
    var nativeSearchForm = document.querySelector('.pb-smart-search-wrapper form');
    if (nativeSearchForm) {
        nativeSearchForm.addEventListener('submit', function(e) {
            var firstResult = document.querySelector('.dropdown-menu.o_search_menu .dropdown-item');
            if (firstResult &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; firstResult.href &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; !firstResult.classList.contains('disabled')) {
                e.preventDefault(); 
                window.location.href = firstResult.href;
            }
        });
    }

    /* =================================================================
       THE B2B CALCULATOR AND VARIANT RENDER ENGINE
       ================================================================= */
    var wrap = document.getElementById('add_to_cart_wrap');
    var specs = document.getElementById('b2b_dynamic_specs');
    var calc = document.getElementById('b2b_tile_calculator');

    if (wrap) {
        if (specs) { wrap.parentNode.insertBefore(specs, wrap); }
        if (calc) { wrap.parentNode.insertBefore(calc, wrap); }
    }

    var calcData = window.b2bCalcData || {};
    var isLoggedIn = window.b2bIsLoggedIn;

    function sync(forceSnap, sourceEl) {
        // Site-1 tile quantities are controlled by the three-way estimator. Preserve legacy logic for HYDROBLOK.
        if (document.getElementById('dt8-verified-packaging-source')) return;
        var activeInput = document.querySelector('input.product_id[name="product_id"]');
        var activeId = activeInput ? activeInput.value : null;
        var d = calcData[activeId] || {sqft: 0, pcs: 0, sqftPerPcs: 0, fullBoxOnly: true, hasBoxPackaging: false, baseBoxOnly: false};

        var sqftInput = document.getElementById('calc_sqft');
        var pcsInput = document.getElementById('calc_pieces');
        var boxInput = document.getElementById('calc_boxes');

        // --- FIX: ALWAYS UPDATE UI LABELS &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; LOCKS FIRST ---
        var sqftLabel = document.getElementById('calc_pkg_sqft');
        var specialBaseBox = (viewMode === 'tile' &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.baseBoxOnly === true &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.sqft &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0);
        var boxCoverageKnown = specialBaseBox || ((viewMode === 'hydroblok') ? (d.pcs &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0) : (d.pcs &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0 &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.sqft &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0));
        d.hasBoxPackaging = boxCoverageKnown;
        if (sqftLabel) { sqftLabel.innerText = boxCoverageKnown &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; viewMode === 'tile' ? d.sqft.toFixed(3) : '—'; }

        var pcsLabel = document.getElementById('calc_pkg_pcs');
        if (pcsLabel) {
            if (specialBaseBox) { pcsLabel.innerText = '1 Set'; }
            else if (boxCoverageKnown) { pcsLabel.innerText = d.pcs; }
            else if (viewMode === 'hydroblok') { pcsLabel.innerText = 'N/A'; }
            else { pcsLabel.innerText = '—'; }
        }

        if (boxInput) {
            boxInput.disabled = !boxCoverageKnown;
            if (!boxCoverageKnown) boxInput.value = '';
        }
        if (!boxCoverageKnown &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.fullBoxOnly &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; viewMode === 'tile') {
            if (sqftInput) { sqftInput.value = ''; sqftInput.disabled = true; }
            if (pcsInput) { pcsInput.value = ''; pcsInput.disabled = true; }
            return;
        } else {
            if (sqftInput) sqftInput.disabled = false;
            if (pcsInput) pcsInput.disabled = false;
        }

        if (pcsInput) {
            pcsInput.removeAttribute('readonly');
            pcsInput.removeAttribute('tabindex');
            pcsInput.style.borderBottom = '2px solid #ccc';
            pcsInput.classList.remove('text-muted');
            if (specialBaseBox) {
                pcsInput.value = '';
                pcsInput.setAttribute('readonly', 'readonly');
                pcsInput.setAttribute('tabindex', '-1');
                pcsInput.style.borderBottom = '1px dotted #ccc';
                pcsInput.classList.add('text-muted');
            }
        }

        if (boxInput) {
            if (d.fullBoxOnly) { boxInput.setAttribute('step', '1'); } 
            else { boxInput.setAttribute('step', '0.001'); }
        }
        // --------------------------------------------------

        var activeEl = sourceEl || document.activeElement;
        var epsilon = 0.01;

        if (specialBaseBox) {
            var rawBaseBoxes = 0;
            if (activeEl === sqftInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; sqftInput) {
                rawBaseBoxes = parseFloat(sqftInput.value || 0) / d.sqft;
            } else if (activeEl === boxInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; boxInput) {
                rawBaseBoxes = parseFloat(boxInput.value || 0);
            } else if (boxInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; boxInput.value !== '') {
                rawBaseBoxes = parseFloat(boxInput.value || 0);
            } else if (sqftInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; sqftInput.value !== '') {
                rawBaseBoxes = parseFloat(sqftInput.value || 0) / d.sqft;
            }

            if (isNaN(rawBaseBoxes) || rawBaseBoxes &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;= 0) {
                if (sqftInput) sqftInput.value = '';
                if (pcsInput) pcsInput.value = '';
                if (boxInput) boxInput.value = '';
                return;
            }

            var finalBaseBoxes = d.fullBoxOnly ? Math.max(0, Math.ceil(rawBaseBoxes - epsilon)) : rawBaseBoxes;
            if (forceSnap === true &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; !d.fullBoxOnly) {
                finalBaseBoxes = Math.max(0, Math.ceil(rawBaseBoxes - epsilon));
            }
            var finalBaseSqft = finalBaseBoxes * d.sqft;

            if (sqftInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; (forceSnap === true || activeEl !== sqftInput)) sqftInput.value = finalBaseSqft.toFixed(3);
            if (pcsInput) pcsInput.value = '';
            if (boxInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; (forceSnap === true || activeEl !== boxInput)) boxInput.value = Number(finalBaseBoxes.toFixed(3));
            return;
        }

        var rawPieces = 0;
        if (activeEl === sqftInput) { 
            rawPieces = parseFloat(sqftInput.value || 0) / d.sqftPerPcs; 
        } else if (activeEl === pcsInput) { 
            rawPieces = parseFloat(pcsInput.value || 0); 
        } else if (activeEl === boxInput) { 
            rawPieces = parseFloat(boxInput.value || 0) * d.pcs; 
        } else { 
            if (pcsInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; pcsInput.value !== "") {
                rawPieces = parseFloat(pcsInput.value);
            } else if (sqftInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; sqftInput.value !== "") {
                rawPieces = parseFloat(sqftInput.value) / d.sqftPerPcs;
            } else {
                rawPieces = parseFloat(boxInput.value || 0) * d.pcs;
            }
        }

        // Now perform the empty-box safety check
        if (isNaN(rawPieces) || rawPieces &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;= 0) { 
            if (sqftInput) sqftInput.value = "";
            if (pcsInput) pcsInput.value = "";
            if (boxInput) boxInput.value = "";
            return;
        }

        var finalPieces = 0, finalBoxes = 0;

        if (!boxCoverageKnown) {
            finalPieces = Math.ceil(rawPieces - epsilon);
            var looseSqft = finalPieces * d.sqftPerPcs;
            if (sqftInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; activeEl !== sqftInput) sqftInput.value = looseSqft.toFixed(3);
            if (pcsInput &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; activeEl !== pcsInput) pcsInput.value = finalPieces;
            return;
        }

        if (d.fullBoxOnly) {
            var rawBoxes = rawPieces / d.pcs;
            finalBoxes = Math.max(0, Math.ceil(rawBoxes - epsilon)); 
            finalPieces = finalBoxes * d.pcs;
        } else {
            finalPieces = Math.ceil(rawPieces - epsilon);
            finalBoxes = finalPieces / d.pcs;
        }

        var finalSqft = finalPieces * d.sqftPerPcs;

        var doSqft = forceSnap === true ? true : (activeEl !== sqftInput);
        if (doSqft) { if (sqftInput) sqftInput.value = finalSqft.toFixed(3); }

        var doPcs = forceSnap === true ? true : (activeEl !== pcsInput);
        if (doPcs) { if (pcsInput) pcsInput.value = finalPieces; }

        var doBox = forceSnap === true ? true : (activeEl !== boxInput);
        if (doBox) { if (boxInput) boxInput.value = (Math.round(finalBoxes * 1000) / 1000); }
    }

    var boxInput = document.getElementById('calc_boxes');
    var sqftInput = document.getElementById('calc_sqft');
    var pcsInput = document.getElementById('calc_pieces');

    if (boxInput) boxInput.addEventListener('input', function(e) { sync(false, e.target); });
    if (sqftInput) sqftInput.addEventListener('input', function(e) { sync(false, e.target); });
    if (pcsInput) pcsInput.addEventListener('input', function(e) { sync(false, e.target); });
    if (boxInput) boxInput.addEventListener('change', function(e) { sync(true, e.target); });
    if (sqftInput) sqftInput.addEventListener('change', function(e) { sync(true, e.target); });
    if (pcsInput) pcsInput.addEventListener('change', function(e) { sync(true, e.target); });

    var target = document.querySelector('input.product_id[name="product_id"]');
    if (target) new MutationObserver(function() { sync(true); }).observe(target, { attributes: true });

    /* THE UNIFIED ACTION BUTTONS */
    var nativeBtn = document.getElementById('add_to_cart');
    if (nativeBtn) {
        if (!document.getElementById('b2b_ghost_cart_btn')) {
