                helperText.innerHTML = '&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;strong style="color: #b58d55; font-size: 0.8rem; letter-spacing: 0.05em; text-transform: uppercase; display: block; margin-bottom: 6px;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;READY FOR THE NEXT STEP?&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/strong&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;span style="font-size: 0.85rem; color: #555;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;Check availability, request a custom quote, or place your order by logging in.&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/span&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;';
                decoyBtn.addEventListener('click', function(e) { e.preventDefault(); window.location.href = '/web/login'; });
            } else {
                decoyBtn.innerHTML = '&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;i class="fa fa-plus" style="margin-right: 8px;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/i&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; ADD TO REQUEST LIST';
                helperText.innerHTML = '&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;strong style="color: #b58d55; font-size: 0.8rem; letter-spacing: 0.05em; text-transform: uppercase; display: block; margin-bottom: 6px;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;READY FOR THE NEXT STEP?&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/strong&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;span style="font-size: 0.85rem; color: #555;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;Click to add to your list to check availability, request a custom quote, or place your order.&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/span&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;';

                decoyBtn.addEventListener('click', function(e) {
