                    var sqftInp = document.getElementById('calc_sqft');
                    var pcsInp = document.getElementById('calc_pieces');

                    var finalSqft = sqftInp ? parseFloat(sqftInp.value || 0) : 0;
                    var finalPieces = pcsInp ? parseFloat(pcsInp.value || 0) : 0;
                    var targetQty = isSqft ? finalSqft.toFixed(3) : finalPieces;

                    if (parseFloat(targetQty) === 0) return;

                    decoyBtn.innerHTML = '&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;i class="fa fa-check" style="margin-right: 8px;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/i&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; ADDED! REDIRECTING...';
                    decoyBtn.style.setProperty('background-color', '#28a745', 'important');
                    decoyBtn.style.setProperty('border-color', '#28a745', 'important');
                    decoyBtn.style.setProperty('color', '#ffffff', 'important');

                    var priceNode = document.querySelector('.product_price .oe_price .oe_currency_value, .oe_price_h4 .oe_price .oe_currency_value');
                    var livePrice = 0;
                    if (priceNode) { livePrice = parseFloat(priceNode.textContent.replace(/[^0-9.]/g, '')) || 0; }

                    var ghostCart = JSON.parse(localStorage.getItem(document.getElementById('dt8_cart_storage_key').value)) || [];
                    var existingItem = ghostCart.find(function(item) { return item.product_id === activeId; });

                    if (existingItem) {
                        existingItem.qty = parseFloat(targetQty);
                        existingItem.price = livePrice;
                    } else {
                        ghostCart.push({
                            product_id: activeId, qty: parseFloat(targetQty), price: livePrice, name: d.name, code: d.code, isSqft: isSqft, sqftPerPcs: d.sqftPerPcs, pcsPerBox: d.pcs, fullBoxOnly: d.fullBoxOnly
                        });
                    }

                    localStorage.setItem(document.getElementById('dt8_cart_storage_key').value, JSON.stringify(ghostCart));

                    var pbUrl = '/website/action/1771'; 
                    if (d.collection &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.collection !== 'False' &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.collection !== '') {
