    function formatMoney(amount) { return (amount &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; amount &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0) ? ("$" + amount.toFixed(2)) : "—"; }

    /* MAIN RENDER ENGINE */
    function render() {
        try {
            var activeInput = document.querySelector('input.product_id[name="product_id"]');
            var activeId = activeInput ? activeInput.value : null;
            var d = variantData[activeId];
            var container = document.getElementById('b2b_dynamic_specs');
            var pdfContainer = document.getElementById('b2b_pdf_tearsheet_container');

            if (!d || !container || !pdfContainer) return;

            var priceNode = document.querySelector('.product_price .oe_price .oe_currency_value, .oe_price_h4 .oe_price .oe_currency_value');
            var livePrice = d.retailPrice; 
            if (priceNode) { livePrice = parseFloat(priceNode.textContent.replace(/[^0-9.]/g, '')) || livePrice; }

            var costSqFt = 0, retailSqFt = 0, costBox = 0, retailBox = 0, costPiece = 0, retailPiece = 0;
            var specialBaseBox = (showSqft &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.baseBoxOnly === true &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.sqft &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0);
            d.hasBoxPackaging = specialBaseBox || ((viewMode === 'hydroblok') ? (d.pcs &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0) : (d.pcs &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0 &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.sqft &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0));

            if (showSqft) {
                var isSqft = d.uom.includes('sq') || d.uom.includes('ft');
                costSqFt = isSqft ? livePrice : (livePrice * d.pcs) / (d.sqft || 1);
                retailSqFt = isSqft ? d.retailPrice : (d.retailPrice * d.pcs) / (d.sqft || 1);
                costPiece = (!specialBaseBox &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.sqftPerPcs &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0) ? costSqFt * d.sqftPerPcs : 0;
                retailPiece = (!specialBaseBox &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; d.sqftPerPcs &amp;amp;amp;amp;amp;amp;amp;amp;amp;gt; 0) ? retailSqFt * d.sqftPerPcs : 0;
                costBox = d.hasBoxPackaging ? costSqFt * d.sqft : 0;
                retailBox = d.hasBoxPackaging ? retailSqFt * d.sqft : 0;
            } else {
                var isBoxUom = d.uom.includes('box') || d.uom.includes('case') || d.uom.includes('carton');
                if (isBoxUom) {
                    costBox = d.hasBoxPackaging ? livePrice : 0; retailBox = d.hasBoxPackaging ? d.retailPrice : 0;
                    costPiece = d.hasBoxPackaging ? costBox / d.pcs : 0; retailPiece = d.hasBoxPackaging ? retailBox / d.pcs : 0;
                } else {
                    costPiece = livePrice; retailPiece = d.retailPrice;
                    costBox = d.hasBoxPackaging ? costPiece * d.pcs : 0; retailBox = d.hasBoxPackaging ? retailPiece * d.pcs : 0;
                }
            }

            var isFullBox = (d.fullBoxOnly === true);
            var soldByText = showSqft ? 'Piece' : 'Each';
            var soldByIcon = '&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;i class="fa fa-cube" style="font-size: 14px; margin-right: 6px;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/i&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;';
            if (isFullBox &amp;amp;amp;amp;amp;amp;amp;amp;amp;amp;&amp;amp;amp;amp;amp;amp;amp;amp;amp;amp; (d.hasBoxPackaging || viewMode === 'tile')) {
                soldByText = 'Full Box Only';
                soldByIcon = '&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;i class="fa fa-cubes" style="font-size: 14px; margin-right: 6px;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/i&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;';
            } else if (d.hasBoxPackaging) {
                if (specialBaseBox) {
