                } else {
                    soldByText = showSqft ? 'Piece or Box' : 'Each or Box';
                }
            }

            var soldByBadge = `
                &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;div class="d-flex align-items-center mt-3" style="color: #888; font-size: 0.65rem; font-weight: 500; text-transform: uppercase; letter-spacing: 0.08em;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                    ${soldByIcon} &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;span&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;Sold By: ${soldByText}&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/span&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/div&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
            `;

            var pricingHTML = '';
            if (isLoggedIn) {
                var isCheckedAttr = window.b2bShowCost ? 'checked' : '';
                var toggleBgColor = window.b2bShowCost ? '#222' : '#ccc';
                var costRowDisplay = window.b2bShowCost ? 'flex' : 'none';

                pricingHTML += `
                &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;div class="d-flex justify-content-end align-items-center mb-3 mt-2 b2b-cost-toggle-row" style="font-size: 0.65rem; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                    &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;span class="text-muted" style="margin-right: 8px;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;MSRP ONLY&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/span&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                    &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;div class="form-check form-switch m-0 p-0" style="display: flex; align-items: center;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                        &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;input class="form-check-input m-0 shadow-none b2b-cost-toggle-input" type="checkbox" ${isCheckedAttr} style="cursor: pointer; width: 32px; height: 16px; background-color: ${toggleBgColor}; border-color: ${toggleBgColor};"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                    &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/div&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                    &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;span style="margin-left: 8px; color: #111;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;SHOW COST&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/span&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/div&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;div class="d-flex text-center py-2 text-uppercase text-muted mb-2" style="font-size: 0.6rem; font-weight: 600; letter-spacing: 0.1em; border-bottom: 1px solid #111;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                    &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;div class="text-start" style="flex: 1 1 0%;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;Pricing&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/div&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                    ${showSqft ? '&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;div style="flex: 1 1 0%;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;SqFt&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/div&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;' : ''}
                    &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;div style="flex: 1 1 0%;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;${unitLabel}&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/div&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                    &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;div class="text-end" style="flex: 1 1 0%;"&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;Box&amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/div&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
                &amp;amp;amp;amp;amp;amp;amp;amp;amp;lt;/div&amp;amp;amp;amp;amp;amp;amp;amp;amp;gt;
