(function(){
  function reflow(){
    var row=document.getElementById('product_detail_main');
    var specs=document.getElementById('dt8-refined-specifications');
    var matches=document.getElementById('dt8-format-alternatives');
    var related=document.getElementById('dt8-related-colours');
    if(!row || !specs || !matches || !related || document.getElementById('dt8-below-hero'))return;
    var shelf=document.createElement('div');shelf.id='dt8-below-hero';
    row.insertAdjacentElement('afterend',shelf);
    shelf.appendChild(specs);shelf.appendChild(matches);shelf.appendChild(related);
    if(!matches.querySelector('.dt8-matched-card'))matches.style.display='none';
    if(!related.querySelector('.dt8-related-card'))related.style.display='none';
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',reflow);else reflow();
})();

(function(){
  /* DT8_HB_MSRP_VARIANT_SYNC_V1_20261016; no XML-sensitive ampersand or comparison operators. */
  function init(){
    var data=document.getElementById('dt8-hb-prices');
    var box=document.getElementById('dt8-hb-pricebox');
    var details=document.getElementById('product_details');
    if(!data || !box || !details || box.dataset.dt8Ready)return;
    box.dataset.dt8Ready='1';
    var nativePrice=details.querySelector('.o_wsale_product_details_content_section_price');
    if(nativePrice ? Boolean(nativePrice.parentNode) : false)nativePrice.insertAdjacentElement('afterend',box);
    var main=document.getElementById('dt8-hb-primary');
    var reference=document.getElementById('dt8-hb-msrp');
    var code=document.getElementById('dt8-hb-sku');
    function money(x){return '$'+x.toLocaleString('en-CA',{minimumFractionDigits:2,maximumFractionDigits:2});}
    function present(n){return Number.isFinite(n)?Math.sign(n)===1:false;}
    function draw(){
      var input=details.querySelector('input.product_id');
      var id=input?input.value:'';
      if(!id)id=new URLSearchParams(window.location.search).get('variant')||'';
      var node=id?data.querySelector('[data-id="'+id+'"]'):null;
      if(!node){main.textContent='Price on request';code.textContent='Select a valid product option';if(reference)reference.textContent='On request';return;}
      var retail=Number(node.getAttribute('data-msrp')||0);
      var dealer=Number(node.getAttribute('data-dealer')||0);
      var price=reference?dealer:retail;
      main.textContent=present(price)?money(price):'Price on request';
      if(reference)reference.textContent=present(retail)?money(retail):'On request';
      code.textContent=node.getAttribute('data-code')||'Selected product';
    }
    function change(){window.setTimeout(draw,170);window.setTimeout(draw,510);}
    details.addEventListener('change',change);
    details.addEventListener('click',change);
    window.addEventListener('pageshow',draw);
    draw();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);
  else init();
})();

(function(){
    function dt8FixNicheDescription(){
        document.querySelectorAll('#wrap p').forEach(function(p){
            var s=(p.textContent||'').replace(/\s+/g,' ').trim();
            if(/^32[”"]?\s*[x×]\s*26[”"]?\s*Recessed Double Arch Niche$/i.test(s)){
                p.textContent='Find the right niche for your design. Choose from the available sizes and styles above; the SKU and per-unit pricing update to match your selection.';
            }
