    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',dt8FixNicheDescription);
    else dt8FixNicheDescription();
})();

(function(){
    var field=document.querySelector('#product_details input.product_template_id');
    var id=field ? Number(field.value) : 0;
    var fixes={
      6604:{old:'44" x 96" x 2" Wallboard',next:'Choose the wallboard size and thickness that suit your project. The selected SKU and per-unit price reflect the panel you choose above.'},
      6621:{old:'72" x 72" Shower Pan w/Drain',next:'Choose your shower pan style, drain position and available dimensions above. The selected SKU and per-unit price follow your choice.'},
      6608:{old:'Joint Sealant Sausages 20 oz.',next:'Choose the HYDRO-BLOK sealant format and container size that suit your installation. The selected SKU and per-unit price follow your choice.'}
    };
    var fix=fixes[id];
    if(!fix)return;
    function norm(s){return String(s||'').replace(/[“”″]/g,'"').replace(/\s+/g,' ').trim().toLowerCase();}
    function apply(){
        document.querySelectorAll('#wrap p').forEach(function(p){
            if(norm(p.textContent)===norm(fix.old))p.textContent=fix.next;
        });
    }
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply);
    else apply();
})();

