 try{nativeRules=JSON.parse(list.getAttribute('data-attribute-exclusions')||'{}');}catch(e){return false;}
 var archived=Array.isArray(nativeRules.archived_combinations)?nativeRules.archived_combinations:[];
 if(!archived.length)return false;
 var groups=Array.from(list.querySelectorAll('li.variant_attribute'));
 var chosen=groups.map(function(g){
  var opts=Array.from(g.querySelectorAll('input[type="radio"][data-value-id][data-attribute-value-id]'));
  return opts.find(function(x){return requested.indexOf(x.getAttribute('data-attribute-value-id'))!==-1;})||opts.find(function(x){return x.checked;});
 });
 if(!chosen.length||chosen.some(function(x){return !x;}))return false;
 function blocked(keys){
  return archived.some(function(row){
