  });
 }
 var selected=chosen.map(function(x){return x.getAttribute('data-value-id');});
 if(!blocked(selected))return false;
 var sizeGroup=groups.findIndex(function(g){return /pan extension size/i.test(g.getAttribute('data-attribute-name')||'');});
 if(sizeGroup===-1)return false;
 var candidates=Array.from(groups[sizeGroup].querySelectorAll('input[type="radio"][data-value-id][data-attribute-value-id]'));
 var replacement=candidates.find(function(x){
  if(x===chosen[sizeGroup])return false;
  var trial=selected.slice();trial[sizeGroup]=x.getAttribute('data-value-id');
  return !blocked(trial);
 });
 if(!replacement)return false;
 chosen[sizeGroup]=replacement;
 var corrected=chosen.map(function(x){return x.getAttribute('data-attribute-value-id');}).join(',');
 if(corrected===requested.join(','))return false;
 url.searchParams.set('attribute_values',corrected);
