  return choices[0]||null;
 }

 /* DT8_HB_GUIDED_DEEPLINK_V2_20261031: redirect archived direct links to the nearest real available variant, no price guessing. */
 function handleDirectLink(){
  var url=new URL(window.location.href),param=url.searchParams.get('attribute_values')||'';
  if(!param){
   if(url.searchParams.get('dt8_hb_combo_corrected')==='1'){
    note.textContent='We selected an available combination. Please confirm the options before ordering.';note.hidden=false;
    url.searchParams.delete('dt8_hb_combo_corrected');window.history.replaceState(window.history.state,'',url.toString());
   }
   return false;
  }
  var requested=param.split(',').filter(Boolean);
  var wanted=groups.map(function(g){return g.inputs.find(function(x){return requested.indexOf(x.getAttribute('data-attribute-value-id'))!==-1;})||g.inputs.find(function(x){return x.checked;});});
  if(wanted.some(function(x){return !x;}))return false;
  if(contains(wanted)){
   if(url.searchParams.get('dt8_hb_combo_corrected')==='1'){
    note.textContent='The original combination was unavailable. We selected the closest available option. Please confirm before ordering.';
    note.hidden=false;url.searchParams.delete('dt8_hb_combo_corrected');
    window.history.replaceState(window.history.state,'',url.toString());
   }
   return false;
  }
  if(url.searchParams.get('dt8_hb_combo_corrected')==='1')return false;
  var corrected=best(0,wanted[0],wanted);
  if(!corrected){
   var ordered=valid.slice();
   ordered.sort(function(x,y){
    function score(c){return c.reduce(function(n,option,i){return n+(option===wanted[i]?1:0);},0);}
    return score(y)-score(x);
   });
   corrected=ordered[0];
  }
  if(!corrected)return false;
  var selection=corrected.map(function(x){return x.getAttribute('data-attribute-value-id');}).join(',');
  if(selection===param)return false;
  url.searchParams.set('attribute_values',selection);
  url.searchParams.delete('variant');
  url.searchParams.set('dt8_hb_combo_corrected','1');
  window.location.replace(url.toString());
  return true;
 }
 if(handleDirectLink())return;

 function render(){
  var current=selected();
  groups.forEach(function(g,i){g.inputs.forEach(function(input){
   var item=input.closest('li.js_attribute_value'),label=input.closest('label');
   if(!item)return;
   var available=!!best(i,input,current);
   var adjusts=available&&!same(best(i,input,current),current)&&input!==current[i];
   item.classList.toggle('dt8-hb-never-valid',!available);
   item.classList.toggle('dt8-hb-auto-adjust',adjusts);
   if(input.disabled!==!available)input.disabled=!available;
   if(label){if(!available){label.setAttribute('aria-disabled','true');label.title='This option is not offered';}
     else{label.removeAttribute('aria-disabled');label.title=adjusts?'Selecting this will also adjust another option to an available combination':'';}}
  });});
 }

 /* DT8_HB_URL_RADIO_RECONCILE_V3_20261031: native Odoo URL and SKU can resolve before radio highlight catches up. Align visual checked radio to the selected real URL variant, without triggering another price update. */
 function syncUrlSelection(){
  var text=new URL(window.location.href).searchParams.get('attribute_values')||'';
  if(!text)return;
  var ids=text.split(',').filter(Boolean);
  var target=groups.map(function(g){return g.inputs.find(function(input){return ids.indexOf(input.getAttribute('data-attribute-value-id'))!==-1;});});
  if(target.some(function(input){return !input;})||!contains(target))return;
  if(!same(selected(),target))target.forEach(function(input){input.checked=true;});
  render();
 }

 function choose(combo,target){
  var before=selected();
  groups.forEach(function(g,i){if(combo[i])combo[i].checked=true;});
  var changed=groups.map(function(g,i){return before[i]!==combo[i]?g.name+': '+(combo[i].getAttribute('data-value-name')||combo[i].title||'available option'):'';}).filter(Boolean);
  note.textContent=changed.length>1?'Available combination selected — '+changed.join('; ')+'.':'';
  note.hidden=!note.textContent;
  suppress=true;target.dispatchEvent(new Event('change',{bubbles:true}));suppress=false;
  window.setTimeout(render,80);window.setTimeout(render,350);window.setTimeout(syncUrlSelection,1000);window.setTimeout(syncUrlSelection,2000);
 }
 details.addEventListener('click',function(ev){
  var item=ev.target&&ev.target.closest?ev.target.closest('li.js_attribute_value'):null;
  if(!item||!list.contains(item))return;
  var input=item.querySelector('input[type="radio"][data-value-id]');
  if(!input)return;
  var index=groups.findIndex(function(g){return g.inputs.indexOf(input)!==-1;});
  if(index<0)return;
  var current=selected(),candidate=best(index,input,current);
  if(!candidate){ev.preventDefault();ev.stopImmediatePropagation();return;}
  var desired=current.slice();desired[index]=input;
  if(!contains(desired)){
   ev.preventDefault();ev.stopImmediatePropagation();choose(candidate,input);
  }
 },true);
 details.addEventListener('change',function(ev){
  if(suppress||!ev.target||!list.contains(ev.target))return;
  var input=ev.target,index=groups.findIndex(function(g){return g.inputs.indexOf(input)!==-1;});
  if(index<0)return;
  var current=selected();
  if(!contains(current)){
   var candidate=best(index,input,current);
   if(candidate)choose(candidate,input);
  }
  window.setTimeout(render,60);window.setTimeout(render,380);window.setTimeout(syncUrlSelection,1200);
 },true);
 render();window.setTimeout(render,600);window.setTimeout(syncUrlSelection,1800);window.addEventListener('pageshow',function(){window.setTimeout(syncUrlSelection,150);});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
